function gameDescription(g){
 const original=String(get(g,'description')||'').trim();
 if(state.lang==='en')return `<p class="game-original-description" lang="en">${esc(original||'No source description available.')}</p>`;
 const id=Number(get(g,'appid'));
 const localized=window.LUDO_LOCALIZED_DESCRIPTIONS?.[id]?.[state.lang];
 const isChineseOriginal=(original.match(/[\u3400-\u9fff]/g)||[]).length>Math.max(12,original.length*.25);
 if(localized||isChineseOriginal){const body=localized||original;const display=state.lang==='zh-TW'?(window.LudoI18n?.trad(body)||body):body;return `<p class="game-local-description">${esc(display)}</p><p class="game-desc-credit">${localized?txt('已接入本地化介绍','已接入在地化介紹','Localized description'):txt('原始商店介绍','原始商店介紹','Original store description')}</p>`;}
 const title=gName(g),genres=String(get(g,'genres')||'').split(';').map(s=>s.trim()).filter(t=>t&&t!=='Indie'&&t!=='Early Access');
 const primary=[...new Set(genres.map(t=>CN_GAME_TAGS[t]).filter(Boolean))].slice(0,3);
 const tagNames=String(get(g,'tags')||'').split(';').map(s=>s.trim());
 const translated=[...new Set(tagNames.map(t=>CN_GAME_TAGS[t]).filter(Boolean))].filter(t=>!primary.includes(t)).slice(0,5);
 const nameChinese=title.replace(/[《》]/g,'');const kind=primary.length?primary.join('、'):'独立游戏';
 const year=get(g,'year'),who=get(g,'developer');
 let lines=[`《${nameChinese}》是一款${kind}作品${year?`（发行年份：${year}）`:''}。`];
 if(translated.length)lines.push(`根据 Steam 商店标签，这款游戏涉及${translated.map(t=>'「'+t+'」').join('、')}等内容。`);
 if(get(g,'earlyAccess'))lines.push('目前的样本信息将其标记为抢先体验游戏。');
 if(get(g,'ai'))lines.push('商店资料中披露了生成式 AI 的使用信息。');
 const zh=lines.join('');const display=state.lang==='zh-TW'?(window.LudoI18n?.trad(zh)||zh):zh;
 return `<p class="game-local-description">${esc(display)}</p><p class="game-desc-credit">${txt('中文资料概览（按类型与标签生成，非官方全文翻译）','中文資料概覽（依類型與標籤整理，非官方全文翻譯）','Summary based on metadata, not an official translation')}</p>${original?`<details class="game-source-details"><summary>${txt('查看 Steam 英文原文','查看 Steam 英文原文','View original Steam text')}</summary><p lang="en">${esc(original)}</p></details>`:''}`;
}

// Steam cover assets are remote and may be blocked when opening a downloaded file.
// We keep a local decorative fallback for the six hero cards and retry alternate CDNs.
const FEAT_IDS=new Set([1623730,2379780,1030300,3164500,3419430,1903340]);
const steamArtHosts=[
 id=>`https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${id}/header.jpg`,
 id=>`https://cdn.cloudflare.steamstatic.com/steam/apps/${id}/header.jpg`,
 id=>`https://cdn.akamai.steamstatic.com/steam/apps/${id}/header.jpg`,
 id=>`https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${id}/capsule_616x353.jpg`,
 id=>`https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/${id}/header.jpg`
];
function steamCover(id,extra=''){
  const local=FEAT_IDS.has(Number(id))?`<img class="cover-fallback-poster" alt="" src="${window.LUDO_OFFLINE_POSTERS?.[id]||`assets/covers/poster_${id}.svg`}"><img class="cover-local-official" alt="" src="${window.LUDO_OFFICIAL_COVERS?.[id]||`assets/covers/official_${id}.jpg`}" onerror="this.remove()">`:'';
  return `${local}<img class="steam-cover-remote ${extra}" alt="" data-steam-cover="${id}" data-cover-try="0" loading="lazy" decoding="async" src="${steamArtHosts[0](id)}">`;
}
const cover=(g,cls='game-cover')=>{const id=get(g,'appid');return `<span class="${cls} cover-frame" data-cover-game="${id}"><span class="cover-fallback-symbol" aria-hidden="true">✦</span>${steamCover(id)}</span>`};
// Event delegation survives client-side page renders and avoids broken-image icons.
document.addEventListener('error',(event)=>{
  const el=event.target;if(!el?.matches?.('img[data-steam-cover]'))return;
  const i=Number(el.dataset.coverTry||0)+1;
  if(i>=steamArtHosts.length){el.remove();return;}
  el.dataset.coverTry=String(i);el.src=steamArtHosts[i](el.dataset.steamCover);
},true);

